// src/bot/commands/leaderboard.ts
var MEDALS = ["\uD83E\uDD47", "\uD83E\uDD48", "\uD83E\uDD49"];
var leaderboard = {
  name: "leaderboard",
  description: "Rank all players by total bankroll (cash + open bets)",
  usage: "/leaderboard",
  handler: async ({ thread }) => {
    const cashRows = await db.select({
      id: users.id,
      username: users.username,
      firstName: users.firstName,
      lastName: users.lastName,
      cashCents: sum(ledger.amountCents)
    }).from(users).leftJoin(ledger, eq(ledger.userId, users.id)).groupBy(users.id);
    const openRows = await db.select({
      userId: bets.userId,
      atRiskCents: sum(bets.costCents)
    }).from(bets).where(eq(bets.status, "open")).groupBy(bets.userId);
    const atRisk = new Map(openRows.map((row) => [row.userId, Number(row.atRiskCents ?? 0)]));
    const ranked = cashRows.map((row) => ({
      ...row,
      totalCents: Number(row.cashCents ?? 0) + (atRisk.get(row.id) ?? 0)
    })).sort((a, b3) => b3.totalCents - a.totalCents);
    if (ranked.length === 0) {
      await thread.post("No players yet — type /start to open an account.");
      return;
    }
    const lines = ranked.map((row, i) => {
      const rank = MEDALS[i] ?? `${i + 1}.`;
      return `${rank} ${displayName(row)} — ${formatDollars(row.totalCents)}`;
    });
    await thread.post(["\uD83C\uDFC6 Leaderboard", "", ...lines].join(`
`));
  }
};

