// src/kalshi/series.ts
var TRACKED_SERIES = [
  { ticker: "KXWCGAME", emoji: "⚽️", title: "World Cup 2026 Games" },
  { ticker: "KXNBAGAME", emoji: "\uD83C\uDFC0", title: "NBA Finals 2026" }
];
var DEFAULT_SERIES_EMOJI = "\uD83C\uDFAF";
function seriesEmoji(seriesTicker) {
  return TRACKED_SERIES.find((s) => s.ticker === seriesTicker)?.emoji ?? DEFAULT_SERIES_EMOJI;
}
function seriesTitle(seriesTicker) {
  const known = TRACKED_SERIES.find((s) => s.ticker === seriesTicker);
  if (known)
    return `${known.emoji} ${known.title}`;
  const stripped = seriesTicker.replace(/^KX/, "");
  const name = stripped.charAt(0).toUpperCase() + stripped.slice(1).toLowerCase();
  return `${DEFAULT_SERIES_EMOJI} ${name}`;
}
function seriesRank(seriesTicker) {
  const index2 = TRACKED_SERIES.findIndex((s) => s.ticker === seriesTicker);
  return index2 === -1 ? TRACKED_SERIES.length : index2;
}

// src/kalshi/client.ts
var import_kalshi_typescript = __toESM(require_dist3(), 1);
var eventsApi = new import_kalshi_typescript.EventsApi;
var marketApi = new import_kalshi_typescript.MarketApi;

// src/kalshi/ingest.ts
var PAGE_LIMIT = 200;
async function ingestEvents(seriesTicker, { status, withNestedMarkets = true } = {}) {
  const events2 = [];
  const milestones = [];
  let cursor;
  do {
    const { data } = await eventsApi.getEvents(PAGE_LIMIT, cursor, withNestedMarkets, true, status, seriesTicker);
    events2.push(...data.events);
    milestones.push(...data.milestones ?? []);
    cursor = data.cursor || undefined;
  } while (cursor);
  return { events: events2, milestones };
}

// src/utils/sync.ts
var cents = (dollars) => dollars == null || dollars === "" ? null : Math.round(parseFloat(dollars) * 100);
var date2 = (iso) => iso ? new Date(iso) : null;
var BETTABLE_HORIZON_MS = 2 * 24 * 60 * 60 * 1000;
var BETTABLE_ALERT_LEAD_MS = 30 * 60 * 1000;
var SYNC_LEAD_MS = 6 * 60 * 60 * 1000;
async function sync(seriesTicker) {
  const { events: kalshiEvents, milestones } = await ingestEvents(seriesTicker, {
    status: "open"
  });
  const milestoneByEvent = indexMilestones(milestones);
  const mirrored = new Map((await db.select({ eventTicker: events.eventTicker, startsAt: events.startsAt }).from(events).where(eq(events.seriesTicker, seriesTicker))).map((r) => [r.eventTicker, r.startsAt]));
  const horizon = new Date(Date.now() + BETTABLE_HORIZON_MS + SYNC_LEAD_MS);
  const menuVisible = (eventTicker) => {
    if (!mirrored.has(eventTicker))
      return false;
    const storedStart = mirrored.get(eventTicker);
    return storedStart == null || storedStart <= horizon;
  };
  let eventCount = 0;
  let marketCount = 0;
  let skippedEvents = 0;
  let settledBets = 0;
  let voidedBets = 0;
  const settlements = [];
  for (const event of kalshiEvents) {
    const milestone = milestoneByEvent.get(event.event_ticker);
    const startsAt = date2(milestone?.start_date);
    const beyondHorizon = startsAt != null && startsAt > horizon;
    if (beyondHorizon && !menuVisible(event.event_ticker)) {
      skippedEvents++;
      continue;
    }
    await upsertEvent(event, milestone);
    eventCount++;
    if (beyondHorizon)
      continue;
    for (const market of event.markets ?? []) {
      await upsertMarket(event, market);
      marketCount++;
      const result = market.result ?? "";
      if (result === "yes" || result === "no") {
        const settled = await settleMarketBets(market.ticker, result);
        settledBets += settled.length;
        if (settled.length)
          settlements.push({ marketTicker: market.ticker, result, bets: settled });
      } else if (result === "void") {
        voidedBets += await voidMarketBets(market.ticker);
      }
    }
  }
  return {
    series: seriesTicker,
    events: eventCount,
    markets: marketCount,
    skippedEvents,
    settledBets,
    voidedBets,
    settlements
  };
}
async function settleOpenBetMarkets() {
  const openMarkets = await db.selectDistinct({ ticker: bets.marketTicker }).from(bets).where(eq(bets.status, "open"));
  let settledBets = 0;
  let voidedBets = 0;
  const settlements = [];
  const BATCH = 50;
  for (let i = 0;i < openMarkets.length; i += BATCH) {
    const tickers = openMarkets.slice(i, i + BATCH).map((r) => r.ticker);
    const { data } = await marketApi.getMarkets(BATCH, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, tickers.join(","));
    for (const market of data.markets ?? []) {
      await updateMarketRow(market);
      const result = market.result ?? "";
      if (result === "yes" || result === "no") {
        const settled = await settleMarketBets(market.ticker, result);
        settledBets += settled.length;
        if (settled.length)
          settlements.push({ marketTicker: market.ticker, result, bets: settled });
      } else if (result === "void") {
        voidedBets += await voidMarketBets(market.ticker);
      }
    }
  }
  return { checkedMarkets: openMarkets.length, settledBets, voidedBets, settlements };
}
async function claimBettableAlerts() {
  const now = new Date;
  const threshold = new Date(now.getTime() + BETTABLE_ALERT_LEAD_MS);
  return db.update(events).set({ bettableAnnounced: true }).where(and(eq(events.bettableAnnounced, false), gt(events.startsAt, now), lte(events.startsAt, threshold), exists(db.select({ ticker: markets.ticker }).from(markets).where(eq(markets.eventTicker, events.eventTicker))))).returning({
    eventTicker: events.eventTicker,
    seriesTicker: events.seriesTicker,
    title: events.title,
    startsAt: events.startsAt
  });
}
async function syncAll() {
  const series = [];
  for (const tracked of TRACKED_SERIES) {
    series.push(await sync(tracked.ticker));
  }
  const settlement = await settleOpenBetMarkets();
  const bettableAlerts = await claimBettableAlerts();
  const settledBets = series.reduce((n, s) => n + s.settledBets, settlement.settledBets);
  const voidedBets = series.reduce((n, s) => n + s.voidedBets, settlement.voidedBets);
  const settlements = [...series.flatMap((s) => s.settlements), ...settlement.settlements];
  return {
    series,
    checkedMarkets: settlement.checkedMarkets,
    settledBets,
    voidedBets,
    settlements,
    bettableAlerts
  };
}
function indexMilestones(milestones) {
  const byEvent = new Map;
  for (const milestone of milestones) {
    for (const ticker of milestone.primary_event_tickers ?? []) {
      const existing = byEvent.get(ticker);
      if (!existing || milestone.details?.status && !existing.details?.status) {
        byEvent.set(ticker, milestone);
      }
    }
  }
  return byEvent;
}
async function upsertEvent(event, milestone) {
  const startsAt = date2(milestone?.start_date);
  const gameStatus = milestone?.details?.status ?? "";
  await db.insert(events).values({
    eventTicker: event.event_ticker,
    seriesTicker: event.series_ticker,
    title: event.title,
    mutuallyExclusive: event.mutually_exclusive,
    startsAt,
    gameStatus
  }).onConflictDoUpdate({
    target: events.eventTicker,
    set: {
      title: event.title,
      mutuallyExclusive: event.mutually_exclusive,
      ...startsAt ? { startsAt } : {},
      gameStatus,
      syncedAt: new Date
    }
  });
}
function marketPrices(market) {
  return {
    yesBid: cents(market.yes_bid_dollars),
    yesAsk: cents(market.yes_ask_dollars),
    noBid: cents(market.no_bid_dollars),
    noAsk: cents(market.no_ask_dollars),
    lastPrice: cents(market.last_price_dollars)
  };
}
async function updateMarketRow(market) {
  await db.update(markets).set({
    status: market.status,
    result: market.result ?? "",
    ...marketPrices(market),
    syncedAt: new Date
  }).where(eq(markets.ticker, market.ticker));
}
async function upsertMarket(event, market) {
  const prices = marketPrices(market);
  await db.insert(markets).values({
    ticker: market.ticker,
    eventTicker: event.event_ticker,
    outcome: market.yes_sub_title,
    status: market.status,
    result: market.result ?? "",
    openTime: date2(market.open_time),
    closeTime: new Date(market.close_time),
    expectedExpirationTime: date2(market.expected_expiration_time),
    ...prices
  }).onConflictDoUpdate({
    target: markets.ticker,
    set: {
      status: market.status,
      result: market.result ?? "",
      openTime: date2(market.open_time),
      closeTime: new Date(market.close_time),
      expectedExpirationTime: date2(market.expected_expiration_time),
      ...prices,
      syncedAt: new Date
    }
  });
}

